  // control" doesn't restrict to Equipment at all — it was voltron's
  // territory before `artifacts` existed and must not become
  // `artifacts:Equipment` just because it happens to be one. Falls through
  // to the text-based scan below for a card that isn't itself a qualifying
  // subtype but restricts its payoff to one (Xorn: "If you would create
  // one or more Treasure tokens...").
  if (def.qualifiable === 'permanentSubtype') {
    const structural = facts.permanentSubtypes.find((s) => ARTIFACT_ARCHETYPE_SUBTYPES.includes(s));
    if (structural) return structural;
  }

  // cardType/permanentSubtype/color narrow to a curated constant rather
  // than the creature-type vocabulary — Kalamax copies *instants*, not
  // creatures; a devotion payoff names a WUBRG color, not a creature type.
  const typeByWord =
    def.qualifiable === 'cardType'
      ? CARD_TYPE_BY_WORD
      : def.qualifiable === 'permanentSubtype'
        ? PERMANENT_SUBTYPE_BY_WORD
        : def.qualifiable === 'color'
          ? COLOR_BY_WORD
          : vocab.typeByWord;

  // rewards/consumes checked first, same order as always — Angel of Glory's
  // Rise depends on rewards being tried before a broader-matching consumes
  // clause could swallow the wrong type first. amplifies is appended for
  // Xorn's sake: its Treasure restriction lives in "If you would create one
  // or more Treasure tokens, instead create..." (amplifies), not a
  // rewards/consumes clause. produces is deliberately excluded — Gothmog's
  // "amass Orcs 1" is genuine go-wide production regardless of the type it
  // happens to create, not a restriction to it.
  const payoffMatchers = [
    ...(def.roles.rewards ?? []),
    ...(def.roles.consumes ?? []),
    ...(def.roles.amplifies ?? []),
  ];
  for (const clause of clauses(facts.text)) {
    // "One of each" means every option equally, not a single restriction —
    // Academy Manufactor replaces creating a Clue, Food, *or* Treasure
    // token with creating all three, so this clause must not qualify as
    // whichever type word it happens to mention first (which the type
    // list before "instead" would do even from a matcher's own match text).
    if (/\bone of each\b/i.test(clause)) continue;
    let hit = false;
    for (const matcher of payoffMatchers) {
      if (typeof matcher === 'function') continue;
      const match = matcher.exec(clause);
      if (!match) continue;
      hit = true;
      // Prefer a type word from the matcher's own match text — Angel of
      // Glory's Rise's "exile all Zombies, then return all Human creature
      // cards from your graveyard to the battlefield" must qualify Human,
      // the thing actually returned, not Zombies, which is merely exiled
      // earlier in the same clause and never part of this match.
      for (const word of wordsIn(match[0])) {
        const type = typeByWord.get(word);
        if (type) return type;
      }
    }
    if (!hit) continue;
    // An ability is never itself a card type, so any type word near an
    // ability-copy clause describes something else entirely — Agrus Kos,
    // Eternal Soldier's "copy that ability for each other creature you
    // control" (the copies' targets) and Echo, Perceptive Prodigy's "...
    // ability you control from a creature source" (what the ability's
    // source is) are not restrictions on what's copied. Coherent only for
    // cardType qualifying, so scoped to it.
    if (def.qualifiable === 'cardType' && /\bability\b/i.test(clause)) continue;
    // No matcher's own match text named a type — Sliver Gravemother's
    // restriction ("Each Sliver creature card ... has encore") sits
    // structurally apart from the bare keyword its matcher hits, so fall
    // back to the whole clause.
    for (const word of wordsIn(clause)) {
      const type = typeByWord.get(word);
      if (type) return type;
    }
  }
  return undefined;
}

function rolesFor(def: ArchetypeDef, facts: CardFacts, vocab: Vocabulary): Role[] {
  const found: Role[] = [];
  for (const role of ROLES) {
    const matchers = def.roles[role];
    if (matchers?.some((m) => matches(m, facts, vocab))) found.push(role);
  }
  return found;
}

/**
 * The creature types a card could possibly relate to.
 *
 * Derived from the card outward rather than by testing every type in the
 * game against it. That is not just an optimisation: looping the full
 * vocabulary meant 647 types x 884 keywords of regex per card, which took
 * 82 seconds across the card pool and made precomputing signals impractical.
 * Scanning the card's own words and intersecting with the known-type set is
 * proportional to the card, not to Magic's type list.
 */
function candidateTypes(facts: CardFacts, vocab: Vocabulary): string[] {
  const found = new Set<string>();
  // Structured, and free.
  for (const type of facts.creatureTypes) found.add(type);
  for (const type of facts.producedTokenTypes) found.add(type);
  // Textual: every word the card uses, looked up rather than searched for.
  for (const word of wordsIn(facts.text)) {
    const type = vocab.typeByWord.get(word);
    if (type) found.add(type);
  }
  return [...found];
}

/** Kindred, one signal per creature type. Membership is structural (the card's
 * own type, or a token type it makes); caring about the type is textual. */
function detectKindred(facts: CardFacts, vocab: Vocabulary): SignalMatch[] {
  const out: SignalMatch[] = [];
  for (const type of candidateTypes(facts, vocab)) {
    const roles: Role[] = [];
    // Structured data only — never the name. Goblin Sharpshooter is a Goblin
    // because its type line says so.
    if (facts.creatureTypes.includes(type)) roles.push('is');
    // "Create two 1/1 red Goblin creature tokens" makes Krenko's Command a
    // Goblin card even though a Sorcery has no creature type.
    if (facts.producedTokenTypes.includes(type)) roles.push('produces');

    // Naming the token's type is not caring about the type — "create two 1/1
    // red Goblin creature tokens" already counted as `produces` above, and
    // must not also read as a payoff. Krenko's Command says "Goblin" exactly
    // once, in the token's name, and is a producer only; Krenko, Mob Boss
    // says it twice — once naming the token, once counting "the number of
    // Goblins you control" — and that second mention is the payoff.
    const caringText = withoutTokenDescriptors(facts.text, type);

    for (const clause of clauses(caringText)) {
      if (!wordPattern(type).test(clause)) continue;
      // Sacrifice reads the COST side only — Sophia's "Sacrifice an
      // artifact token: Put a +1/+1 counter on each Dog you control" must
      // not register as consuming Dogs merely because "Dog" appears in the
      // effect. Tap/discard/exile aren't restricted the same way; nothing
      // in the corpus needed it and widening them isn't this fix's job.
      const consumesType = sacrificesKind(clause, type) || /\btap\b|\bdiscard\b|\bexile\b/i.test(clause);
      if (consumesType) {
        roles.push('consumes');
        // An activated ability is "cost: effect", so a clause that spends the
        // type also hands something back. Lathril's "Tap ten untapped Elves
        // you control: Each opponent loses 10 life" consumes Elves *and*
        // rewards you for having had them.
        if (clause.includes(':')) roles.push('rewards');
      }
      if (
        /\bget\b|\bgains?\b|\bhas\b|\bhave\b|whenever|for each|number of|search|\blose\b|\bloses\b/i.test(
          clause,
        )
      ) {
        roles.push('rewards');
      }
      // Archetype-scoped, not generic hexproof: this clause already had to
      // name the type to reach this point (the `wordPattern(type)` guard
      // above), so "Sliver creatures you control have indestructible" earns
      // `protects` for kindred:Sliver specifically — a card that just grants
      // hexproof to "target creature" never reaches this branch at all.
      if (/\b(?:indestructible|hexproof|protection from|shroud|ward)\b/i.test(clause)) {
        roles.push('protects');
      }
      // Tribal mana and cost reduction (docs/signals-rework.md Phase E,
      // kindred's own lifecycle) — the named-type counterpart of the
      // wildcard branch's own tribal-mana patterns above, plus the one
      // cost-reduction shape the corpus actually has: Gemhide Sliver and
      // Manaweft Sliver grant a mana ability to the type ("Sliver creatures
      // you control have '{T}: Add one mana of any color.'"), Sliver Hive
      // restricts spending to it, and Thrumming Hivepool's Affinity for
      // Slivers is a keyword ability, not a "costs less to cast" text
      // pattern — so it needs its own check rather than reusing the
      // wildcard's, which never fires on a named type.
      if (
        /\bhave\s*["“]?\{T\}:\s*Add\b/i.test(clause) ||
        /\bspend this mana only to (?:cast|activate)\b/i.test(clause) ||
        /\baffinity for\b/i.test(clause)
      ) {
        roles.push('enables');
      }
      // Tutors (kindred's own lifecycle): "search your library for a
      // Sliver card" — Sliver Overlord. Card-selection scoped to a *named*
      // type (rather than the wildcard's own "chosen type") wasn't found
      // anywhere in the corpus, so it's left uncovered here rather than
      // invented — see docs/archetypes.md's "Known tensions".
      if (/\bsearch your library\b/i.test(clause)) {
        roles.push('produces');
      }
    }

    if (roles.length === 0) continue;
    out.push({
      archetype: 'kindred',
      label: `${type} Kindred`,
      description: `${pluralOfType(type)}, and cards that care about having them.`,
      weight: 15,
      qualifier: type,
      qualifierKind: 'creatureType',
      roles: [...new Set(roles)],
    });
  }

  // Wildcard kindred: "choose a creature type" (Herald's Horn, Vanquisher's
  // Banner, Realmwalker) supports EVERY kindred theme in the deck, not one
  // of its own — docs/archetypes.md and docs/signals-rework.md Phase E.
  // Path of Ancestry reads its commander's type dynamically rather than
  // asking the player to choose one, but is the same shape: it helps
  // whichever kindred theme the deck actually has.
  const isWildcardKindred =
    /\bchoose a creature type\b/i.test(facts.text) ||
    /\bshares? a creature type with your commander\b/i.test(facts.text);
  if (isWildcardKindred) {
    const wildcardRoles: Role[] = [];
    // Cost reduction and mana restricted to the chosen type turns the
    // tribal engine on, the same shape `enables` already covers elsewhere
    // — Herald's Horn, Gathering Stone, Secluded Courtyard, Unclaimed
    // Territory, Three Tree City.
    if (
      /of the chosen type cost \{?\d+\}? less to cast\b/i.test(facts.text) ||
      /spend this mana only to (?:cast|activate)\b/i.test(facts.text) ||
      /equal to the number of creatures you control of the chosen type\b/i.test(facts.text)
    ) {
      wildcardRoles.push('enables');
    }
    // Card selection scoped to the chosen type — Herald's Horn, Gathering
    // Stone, Realmwalker.
    if (
      /\blook at the top card of your library\b/i.test(facts.text) ||
      /cast creature spells of the chosen type from\b/i.test(facts.text)
    ) {
      wildcardRoles.push('produces');
    }
    // Lords/anthems and cast-triggered payoffs scoped to the chosen type —
    // Vanquisher's Banner; Path of Ancestry's scry on casting a creature
    // that shares its type with the commander.
    if (
      /of the chosen type get \+\d+\/\+\d+\b/i.test(facts.text) ||
      /whenever you cast a creature spell of the chosen type\b/i.test(facts.text) ||
      /shares? a creature type with your commander\b/i.test(facts.text)
    ) {
      wildcardRoles.push('rewards');
    }
    if (wildcardRoles.length > 0) {
      out.push({
        archetype: 'kindred',
        label: 'Kindred (any type)',
        description:
          'Reads whichever creature type you choose — supports every tribal theme in the deck at ' +
          'once, rather than forming one of its own.',
        weight: 15,
        qualifier: '*',
        qualifierKind: 'creatureType',
        roles: [...new Set(wildcardRoles)],
      });
    }
  }

  // Changeling (CR 702.73a, docs/signals-rework.md Phase E): "This card is
  // every creature type" — unconditionally, not a deck-building choice like
  // the wildcard above. Realmwalker, Chomping Changeling, Flock Impostor and
  // Crib Swap none mention a specific type anywhere in their own text
  // (`candidateTypes` above finds nothing to loop for any of them), so the
  // per-type loop never sees them for anything but their own printed type —
  // Realmwalker registers only as `kindred:Shapeshifter[is]`, understating a
  // card that is, as a rules fact, equally a Sliver, a Goblin, and everything
  // else.
  //
  // Pushed unqualified rather than enumerating every type in scope: that
  // reuses Phase B's existing "unqualified supports qualified" fold
  // (`groupByTheme`) and `ownSignalContains`'s existing undefined-qualifier
  // check (synergy.ts) for free — the exact mechanism Wilhelt's unqualified
  // reanimation spell already relies on — rather than looping Magic's
  // ~300-type catalog per changeling card, which is what `is_changeling`
  // being a stored flag instead of an expanded `creatureTypes` list exists to
  // avoid (see `candidateTypes`'s own doc comment on why that loop is scoped
  // to a card's own text in the first place).
  //
  // `is` only, deliberately never `rewards`: Changeling is structural — the
  // card IS every type — not a claim that it CARES about any of them. That
  // keeps kindred's own definingRequirement (`rewards` x2) doing its job
  // unchanged: a deck full of changelings and nothing else still reports no
  // kindred theme, the same as a deck full of plain, passive tribe members
  // does today. It is also why this needs no depth-gate the way the wildcard
  // fold above does — crediting a changeling to a specific type is not an
  // assumption about a future player choice, it is already, unconditionally,
  // true of the printed card.
  if (facts.isChangeling) {
    out.push({
      archetype: 'kindred',
      label: 'Kindred (every type)',
      description: 'Changeling: this card is every creature type, and supports every kindred theme in the deck.',
      weight: 15,
      qualifier: undefined,
      qualifierKind: undefined,
      roles: ['is'],
    });
  }

  return out;
}

/**
 * Keyword care, one signal per keyword.
 *
 * A keyword on its own is not a synergy — Trample is a good thing to have,
 * not a deck. What matters is a commander that *cares* about the keyword
 * (grants it, or triggers off it), which is the same active-role test kindred
 * uses. Having the keyword is `is` and never qualifies a commander on its own.
 */
function detectKeywordCare(facts: CardFacts, vocab: Vocabulary): SignalMatch[] {
  const out: SignalMatch[] = [];
  for (const keyword of candidateKeywords(facts, vocab)) {
    if (IGNORED_KEYWORDS.has(keyword.toLowerCase())) continue;
    const roles: Role[] = [];
    if (facts.keywords.includes(keyword)) roles.push('is');
    // Reuses detectKindred's own word-or-plural matcher — "Foods", "Clues"
    // and "Treasures" never matched a bare, unpluralised keyword before.
    const pattern = wordPattern(keyword);
    for (const clause of clauses(facts.text)) {
      if (!pattern.test(clause)) continue;
      // "Creatures you control gain trample" / "have flying" — granting it to
      // others, which is the Craterhoof shape.
      if (/\b(?:gains?|have|has|gets?)\b/i.test(clause)) roles.push('produces');
      if (/whenever|for each|number of/i.test(clause)) roles.push('rewards');
    }
    if (roles.length === 0) continue;
    out.push({
      archetype: 'keywordCare',
      label: keyword,
      description: `Cards with ${keyword}, where the commander actually cares about it.`,
      weight: 8,
      qualifier: keyword,
      qualifierKind: 'keyword',
      roles: [...new Set(roles)],
    });
  }
  return out;
}

/**
 * Keywords kept out of `keywordCare` entirely — Phase D
 * (docs/signals-rework.md), replacing the original single `EXCLUDED_KEYWORDS`
 * set once C1-C4 shipped.
 *
 * Deliberately short. The original design sketch for this phase assumed that
 * once a dedicated archetype reads a keyword by name (`f.keywords.includes`),
 * a parallel `keywordCare` theme for the same keyword is pure duplication —
 * but `f.keywords` only ever reflects a card's *own* printed keyword, and
 * most of those checks are function matchers that read exactly that array,
 * never `keywordCare`'s own text-scanning "grants this to something else"
 * pattern (`/\b(?:has|have|gains?|gets?)\b[^.\n]*\bKEYWORD\b/i`-shaped). A
 * card that *grants* Cascade/Storm/Suspend/Convoke to spells it casts, or
 * that grants Persist/Undying to creatures it doesn't itself have, never
 * shows up in the "owns the keyword" check at all. Building the full
 * three-bucket split and then re-measuring against the real card pool (not
 * just spot checks) caught this directly: an early version of this set
 * included every keyword `freeSpells`/`storm`/`cyclingDiscard`/`politics`
 * read by name, and re-importing against the real Scryfall snapshot dropped
 * 14 real commanders (Jhoira of the Ghitu, Kang Prime — grant Suspend;
 * Prismari, the Inspiration — grants Storm; Peri Brown — grants Convoke;
 * Wildsear/Yidris/Zhulodok — grant Cascade; Glorfindel/Kenessos/Alrund —
 * care about Scry, never covered by any dedicated archetype at all; Okaun/
 * Tanazir Quandrix/The Thing/Vorel — the generic cross-resource "Double" tag,
 * likewise never covered elsewhere) to zero active signals, a real
 * regression the "zero commanders" coverage report (Phase F) exists
 * specifically to catch. Only two kinds of keyword survive that check:
 *  - **The Partner family**, unchanged from before this phase — it says who
 *    can be your commander, not what your deck wants to do, and it isn't a
 *    grantable ability at all.
 *  - **A keyword whose "grants this to something else" shape is positively,
 *    separately covered**, checked line by line rather than assumed:
 *    Lifelink (`lifegain`'s own granting regex, not just its
 *    `f.keywords.includes` check), Persist/Undying (`recursion`'s own
 *    `/\bhas (?:persist|undying)\b|\bhave (?:persist|undying)\b/i` grant
 *    pattern, verified against Isilu, Carrier of Twilight and Mikaeus, the
 *    Unhallowed), and Crew/Treasure (`artifacts`'s `is` role reads the type
 *    line's own printed subtype directly — a structural fact, not a
 *    "granted" one, so there is no missing shape to begin with).
 * Everything else stays in `keywordCare` under its own name, same as before
 * this phase — including every keyword this phase's own original plan named
 * as an "ability word" candidate for this set (Double, Scry among them):
 * re-measurement found real, uncovered commanders behind both.
 */
const IGNORED_KEYWORDS = new Set([
  'partner',
  'partner with',
  'friends forever',
  'choose a background',
  "doctor's companion",
  'lifelink',
  'persist',
  'undying',
  'crew',
  'treasure',
]);

/**
 * Keywords real enough to build a deck around that mere possession — no
 * separate card that explicitly "cares" — is itself real evidence, the same
 * way Kindred's own "bodies" lifecycle slot counts membership rather than
 * requiring a lord. `definingRequirement` reads this to relax `keywordCare`'s
 * usual "needs a card that actively cares" bar to "needs a card that has it"
 * for exactly these keywords.
 *
 * Flashback and Escape are genuine "cast from the graveyard as a resource,
 * without returning it to hand" mechanics, deliberately excluded from
 * `recursion`'s own pattern as "a different plan" (docs/archetypes.md) that
 * was never actually built — real, well-known, uncovered mechanics rather
 * than an ability word. `IGNORED_KEYWORDS`'s own doc comment covers why this
 * set stayed short rather than absorbing more of the catalog: most keywords
 * that looked redundant with a dedicated archetype turned out not to be,
 * once the "grants this to something else" shape was checked and not just
 * the "has this itself" shape.
 */
const MECHANIC_KEYWORDS = new Set(['flashback', 'escape']);

/** The keywords a card could possibly relate to. Same inversion as
 * `candidateTypes` — look up the card's own words instead of testing all 884
 * keywords against it. Multi-word keywords ("first strike") can't be found by
 * single-word lookup, so those few are still tested directly. */
function candidateKeywords(facts: CardFacts, vocab: Vocabulary): string[] {
  const found = new Set<string>();
  for (const keyword of facts.keywords) found.add(keyword);
  for (const word of wordsIn(facts.text)) {
    const keyword = vocab.keywordByWord.get(word);
    if (keyword) found.add(keyword);
  }
  const lowerText = facts.text.toLowerCase();
  for (const keyword of vocab.multiWordKeywords) {
    if (lowerText.includes(keyword.toLowerCase())) found.add(keyword);
  }
  return [...found];
}

/**
 * Which role is an archetype's identity, and how many citable cards must
 * show it before the archetype is reported at all.
 *
 * Membership (any role) still counts cards once this bar is cleared — a
 * theme's card count is not limited to the defining-role cards — but
 * membership alone cannot clear it. `kindred` is generated per creature type
 * rather than listed in `ARCHETYPES`, so it is special-cased here rather than
 * carrying its own `ArchetypeDef`. `keywordCare` is likewise absent from
 * `ARCHETYPES` and so falls through to the default (`rewards` x1) — granting
 * a keyword is `produces`, not `rewards`, so this is what stops a commander
 * that merely hands out Flying from reading as a Flying deck — *except* for
 * `MECHANIC_KEYWORDS` (Phase D, docs/signals-rework.md), where mere
 * possession is real evidence on its own; `qualifier` is only ever read for
 * that one carve-out, and only `keywordCare` signals set it to a keyword name.
 */
export function definingRequirement(archetype: string, qualifier?: string): { role: Role; minimum: number } {
  if (archetype === 'kindred') {
    // "Ten Wizards plus one incidental pump is not a Wizard deck" — see
    // archetypes.md. Membership is structural and free to claim, so kindred
    // needs more than one card that actually cares.
    return { role: 'rewards', minimum: 2 };
  }
  if (archetype === 'keywordCare' && qualifier && MECHANIC_KEYWORDS.has(qualifier.toLowerCase())) {
    return { role: 'is', minimum: 1 };
  }
  const def = ARCHETYPES.find((a) => a.key === archetype);
  return { role: def?.definingRole ?? 'rewards', minimum: def?.definingMinimum ?? 1 };
}

/** Whether a kindred signal's roles show the card actually caring about the
 * type, not merely making tokens of it — the same "produces alone doesn't
 * count" line `findQualifier`'s own comment draws for Gothmog/amass,
 * generalised so `detectSignals` can borrow across archetypes with it. */
function caresBeyondProduction(roles: Role[]): boolean {
  return roles.some((r) => r !== 'produces' && ACTIVE_ROLES.includes(r));
}

/**
 * A creature-type qualifier borrowed from this same card's own kindred
 * signals, for a `creatureType`-qualifiable archetype match whose own
 * `findQualifier` scan came back empty.
 *
 * Only tried when the archetype's *own* match on this card is `produces`
 * alone (see the caller) — a card whose match also carries a `consumes` or
 * `rewards` role of its own already has a real, if generic, identity in that
 * archetype, and an unrelated type mentioned elsewhere on the same card must
 * not hijack it. A commander that generically "Sacrifice a creature: Draw a
 * card" and, completely separately, buffs a tribe it doesn't otherwise
 * interact with must not read as Aristocrats (that tribe) — that outlet
 * really does take any creature. `produces` alone is different: it is never
 * itself a restriction (Gothmog's "amass Orcs 1" is genuine go-wide
 * production regardless of the type it happens to create — see
 * `findQualifier`'s own comment above), so a produces-only match has no
 * identity of its own to protect, and a card can independently earn an
 * *active*, non-produces kindred signal for that exact type from a
 * *different* clause. Ajani, Nacatl Pariah only ever matches `goWide` via
 * `produces` (his token-making clause) — `findQualifier` correctly leaves
 * him unqualified — but his "Whenever one or more other Cats you control
 * die..." clause independently earns `kindred:Cat` an active `rewards`
 * role, which is real evidence `goWide` can borrow.
 *
 * Exactly one qualifying type, never more, never the kindred wildcard ('*')
 * — two or more real candidates, or zero, and this stays unqualified rather
 * than guessing, the same conservative posture `findQualifier` itself takes
 * for "one of each" and ability-copy clauses.
 */
function borrowedCreatureTypeQualifier(kindredSignals: SignalMatch[]): string | undefined {
  const types = new Set(
    kindredSignals
      .filter((s) => s.qualifier && s.qualifier !== '*' && caresBeyondProduction(s.roles))
      .map((s) => s.qualifier!),
  );
  return types.size === 1 ? [...types][0] : undefined;
}

/** Every archetype this card participates in, and how. */
export function detectSignals(facts: CardFacts, vocab: Vocabulary): SignalMatch[] {
  const out: SignalMatch[] = [];
  const kindredSignals = detectKindred(facts, vocab);

  for (const def of ARCHETYPES) {
    const roles = rolesFor(def, facts, vocab);
    if (roles.length === 0) continue;
    let qualifier = def.qualifiable ? findQualifier(facts, def, vocab) : undefined;
    let qualifierSource: SignalMatch['qualifierSource'];
    // Only a produces-only match is eligible to borrow — see
    // borrowedCreatureTypeQualifier's own comment for why a match that also
    // carries a role of its own (Siege-Gang Commander's "Sacrifice a
    // Goblin", generic though findQualifier can't read it — or a fully
    // untyped "Sacrifice a creature: Draw a card") must not be hijacked by
    // an unrelated type mentioned elsewhere on the card.
    if (def.qualifiable === 'creatureType' && !qualifier && roles.every((r) => r === 'produces')) {
      const borrowed = borrowedCreatureTypeQualifier(kindredSignals);
      if (borrowed) {
        qualifier = borrowed;
        qualifierSource = 'kindred';
      }
    }
    out.push({
      archetype: def.key,
      label: qualifier ? `${def.label} (${qualifier})` : def.label,
      description: def.description,
      weight: def.weight,
      qualifier,
      qualifierKind: qualifier ? def.qualifiable : undefined,
      qualifierSource,
      roles,
      archetypeLabel: def.label,
    });
  }

  out.push(...kindredSignals);
  out.push(...detectKeywordCare(facts, vocab));
  return out;
}

/**
 * Presentation details for a signal read back out of storage.
 *
 * The `card_signals` table records what a card *is* — archetype, qualifier,
 * roles — and deliberately not how to label it. Labels and weights are
 * presentation, and storing them would mean a reworded description needed a
 * full re-import to take effect. This rebuilds them from the catalog instead.
 */
export function archetypeDisplay(
  archetype: string,
  qualifier: string | null,
): { label: string; description: string; weight: number; archetypeLabel: string } {
  if (archetype === 'kindred' && qualifier) {
    return {
      label: `${qualifier} Kindred`,
      description: `${pluralOfType(qualifier)}, and cards that care about having them.`,
      weight: 15,
      archetypeLabel: 'Kindred',
    };
  }
  if (archetype === 'keywordCare' && qualifier) {
    return {
      label: qualifier,
      description: `Cards with ${qualifier}, where the commander actually cares about it.`,
      weight: 8,
      archetypeLabel: qualifier,
    };
  }

  const def = ARCHETYPES.find((a) => a.key === archetype);
  if (!def) {
    // An archetype in the database that the catalog no longer defines — the
    // shape of things after a rename without a re-import. Degrade to the raw
    // key rather than crashing; the next import drops the row.
    return { label: archetype, description: '', weight: 10, archetypeLabel: archetype };
  }
  return {
    label: qualifier ? `${def.label} (${qualifier})` : def.label,
    description: def.description,
    weight: def.weight,
    archetypeLabel: def.label,
  };
}

