      keywords: '["Trample"]',
      oracle_text: 'Trample\nWhenever you discard a card, put a +1/+1 counter on Ivora.',
    });
    assert.deepStrictEqual(rolesOf(signalsFor(ivoraSecondAbility), 'cyclingDiscard'), ['rewards']);
