// ---------------------------------------------------------------------------
// Detection
// ---------------------------------------------------------------------------

/** Splits text into clauses, so a qualifier is only picked up from the same
 * sentence as the payoff it restricts. */
function clauses(text: string): string[] {
  return text.split(/[.;\n]/).filter((c) => c.trim().length > 0);
}

/**
 * The creature type a qualifiable archetype's payoff is restricted to, if any.
 *
 * Only a type mentioned in the same clause as the payoff counts — a commander
 * that reanimates anything and separately happens to mention Goblins is not a
 * Goblin-restricted reanimator.
 */
function findQualifier(facts: CardFacts, def: ArchetypeDef, vocab: Vocabulary): string | undefined {
  // Counters' qualifying evidence usually lives in the PRODUCES clause
  // itself ("enters with three +1/+1 counters" has no separate payoff
  // clause to restrict from), not just rewards/consumes — so every clause
  // is a candidate, and findCounterKind is precise enough on its own not to
  // need pre-filtering by which role matched.
  if (def.qualifiable === 'counterType') {
    for (const clause of clauses(facts.text)) {
      const kind = findCounterKind(clause);
      if (kind) return kind;
    }
    return undefined;
  }

  // gameState's five named states already come precomputed, keyword-aware,
  // onto CardFacts — see findAllGameStates.
  if (def.qualifiable === 'gameState') {
    return facts.gameStates[0];
  }

